phase1.code:
// ---- if let is a concise way to match a single pattern ----

// ---- Basic if let ----
fn main() {
    let some_number = Some(42);
    let none: Option<i32> = None;

    // ---- Using if let with Option ----
    if let Some(n) = some_number {
        println!("Number: {}", n);
    }

    if let Some(n) = none {
        println!("This won't print: {}", n);
    } else {
        println!("No number found");
    }

    // ---- Using if let with Result ----
    let result: Result<i32, String> = Ok(42);
    let error: Result<i32, String> = Err("Error".to_string());

    if let Ok(value) = result {
        println!("Success: {}", value);
    }

    if let Err(e) = error {
        println!("Error: {}", e);
    }

    // ---- Using if let with enums ----
    enum Direction {
        Up,
        Down,
        Left,
        Right,
    }

    let dir = Direction::Up;

    if let Direction::Up = dir {
        println!("Going up!");
    }

    // ---- if let with structs ----
    struct Point {
        x: i32,
        y: i32,
    }

    let point = Point { x: 10, y: 20 };

    if let Point { x: 10, y } = point {
        println!("x is 10, y is {}", y);
    }

    // ---- while let ----
    let mut numbers = vec![1, 2, 3, 4, 5];

    // While let with Option
    while let Some(n) = numbers.pop() {
        println!("Popped: {}", n);
    }

    // ---- while let with custom enum ----
    enum State {
        Running,
        Paused,
        Stopped,
    }

    let mut states = vec![State::Running, State::Running, State::Paused, State::Stopped];

    while let Some(state) = states.pop() {
        match state {
            State::Running => println!("Still running..."),
            State::Paused => println!("Paused!"),
            State::Stopped => {
                println!("Stopped!");
                break;
            }
        }
    }

    // ---- if let with multiple patterns ----
    enum Action {
        Move { x: i32, y: i32 },
        Attack { target: String },
        UseItem(String),
        Wait,
    }

    let action = Action::Attack { target: String::from("Goblin") };

    if let Action::Attack { target } = action {
        println!("Attacking {}", target);
    }

    // ---- if let with guards ----
    let some_value = Some(42);

    if let Some(n) = some_value {
        if n > 50 {
            println!("Large number: {}", n);
        } else {
            println!("Small number: {}", n);
        }
    }

    // ---- if let vs match ----
    // Use if let when you only care about one pattern
    // Use match when you care about multiple patterns

    let value = Some(42);

    // if let (shorter, only one case)
    if let Some(n) = value {
        println!("Value exists: {}", n);
    }

    // match (longer, can handle all cases)
    match value {
        Some(n) => println!("Value exists: {}", n),
        None => println!("Value is None"),
    }
}

